package main

var learnJava = learnTopic{
	Name:   "Java",
	Match:  []string{"java", ".java"},
	Source: "Java Language Specification SE 25 (4.8, 6.1, 15.21.3) · JEPs 222, 286, 330, 361, 378, 390, 394, 395, 409, 421, 431, 440, 441, 444, 456, 458, 467, 511, 512 · JDK 25 API: Optional, List, Stream, String, ExecutorService, Vector, java.time · Java Tutorials: try-with-resources",
	Sections: []learnSection{
		{Title: "Variables and strings", Keys: []string{"=", "string", "int"}, Items: []learnItem{
			{Use: "var", Why: "Lets the compiler work out the type of a local variable from its value. Java 10+. Only for locals with a starting value and loop variables. Not for fields, parameters or return types.",
				Like: "Like a label printer that reads the box and prints the right label for you. The box still has one fixed label.", Example: "var users = new ArrayList<User>();\nvar reader = Files.newBufferedReader(path);"},
			{Use: "final", Why: "A variable that can be given a value only once. A lambda may only use local variables that are final or never changed after they are set.",
				Like: "Like writing in pen instead of pencil: once it is on the page, it stays.", Example: "final int limit = config.maxItems();\nitems.removeIf(i -> i.size() > limit);"},
			{Use: "\"\"\" text block \"\"\"", Keys: []string{"\"\"\""}, Why: "A string over several lines. Java 15+. The opening \"\"\" must end its line. The shared indentation on the left is removed.",
				Like: "Like pasting a letter into a frame exactly as written, with the margin trimmed to fit.", Example: "String sql = \"\"\"\n  SELECT id, name FROM users\n  \"\"\";"},
			{Use: "a.equals(b)", Keys: []string{"equals"}, Why: "Compares the contents of two strings or objects. == on objects only tells you if both names point to the same object.",
				Like: "Like checking that two books have the same words, not that they are the same copy on the shelf.", Example: "if (\"admin\".equals(user.role())) {\n  grantAccess(user);\n}"},
			{Use: "\"%d items\".formatted(n)", Keys: []string{"formatted", "string.format"}, Why: "Fills %d, %s and other placeholders with values. Java 15+. It works like String.format.",
				Like: "Like a form letter with blanks: the values are written into the blanks.", Example: "String msg = \"%d items in %s\".formatted(count, cart);"},
			{Use: "s.isBlank() · s.strip()", Keys: []string{"isblank", "strip", "lines", "repeat"}, Why: "isBlank is true for an empty string or one with only spaces. strip removes spaces at both ends. Java 11+.",
				Like: "Like checking if a page is empty, and trimming the white edges off a photo.", Example: "String name = input.strip();\nif (name.isBlank()) return;"},
		}},
		{Title: "Naming", Keys: []string{"class", "package", "interface"}, Items: []learnItem{
			{Use: "class OrderLine", Why: "Class and interface names are nouns. Each word starts with a capital letter (UpperCamelCase).",
				Like: "Like the name on a shop sign: a thing, written with capitals.", Example: "public class OrderLine {\n  private final int quantity;\n}"},
			{Use: "void sendInvoice()", Keys: []string{"void"}, Why: "Method names are verbs. The first word is lowercase, the next words start with a capital (lowerCamelCase).",
				Like: "Like a task on a to-do list: it starts with what to do.", Example: "public void sendInvoice(Order order) {\n  mailer.send(order.email(), render(order));\n}"},
			{Use: "static final int MAX_SIZE", Keys: []string{"static"}, Why: "Constants are all capitals, with _ between words.",
				Like: "Like a road sign in capital letters: fixed, and easy to spot.", Example: "private static final int MAX_SIZE = 100;"},
			{Use: "package com.example.shop", Why: "Package names are all lowercase. They start with your internet domain written backwards.",
				Like: "Like a postal address written country first, then city, then street.", Example: "package com.example.shop.orders;"},
		}},
		{Title: "Data types", Keys: []string{"new"}, Items: []learnItem{
			{Use: "record Point(int x, int y) {}", Keys: []string{"record"}, Why: "A class that only carries data. Java 16+. Java writes the constructor, equals, hashCode, toString and the readers x() and y().",
				Like: "Like a printed receipt: the values are fixed when it is made, and it reads the same to everyone.", Example: "record Point(int x, int y) {}\nvar p = new Point(3, 4);\nint sum = p.x() + p.y();"},
			{Use: "Point { if (x < 0) throw … }", Keys: []string{"compact"}, Why: "A compact constructor: the record name with no list of parameters. Use it to check values. The fields are set for you at the end.",
				Like: "Like a guard at a door who checks each ticket before the person goes in.", Example: "record User(String name) {\n  User { Objects.requireNonNull(name); }\n}"},
			{Use: "sealed interface Shape permits", Keys: []string{"sealed", "permits", "non-sealed"}, Why: "Lists every type allowed to extend it. Java 17+. Each listed type must be final, sealed or non-sealed. Records are already final.",
				Like: "Like a guest list at the door: only the names on it may come in.", Example: "sealed interface Shape permits Circle, Square {}\nrecord Circle(double r) implements Shape {}\nrecord Square(double side) implements Shape {}"},
			{Use: "Optional<User>", Keys: []string{"optional"}, Why: "A return type for a method that may have no result. The JDK says it is meant mainly for return types. An Optional variable must never be null itself.",
				Like: "Like a parcel box that may be empty: you open it and check, instead of finding no box at all.", Example: "Optional<User> findByEmail(String email) {\n  return Optional.ofNullable(users.get(email));\n}"},
		}},
		{Title: "Pattern matching", Keys: []string{"switch", "case", "instanceof"}, Items: []learnItem{
			{Use: "if (o instanceof String s)", Why: "Checks the type and names the value in one step. Java 16+. s can be used where the check is certain to be true.",
				Like: "Like opening a door marked 'Kitchen' and already knowing you are in the kitchen.", Example: "if (obj instanceof String s && !s.isEmpty()) {\n  System.out.println(s.length());\n}"},
			{Use: "case A, B -> …", Keys: []string{"->", "yield"}, Why: "Arrow cases run only their own code: no fall-through and no break. Java 14+. In a block, yield gives the value.",
				Like: "Like a lift button: you press 3 and it stops at 3, not at every floor after it.", Example: "case SATURDAY, SUNDAY -> \"weekend\";\ncase MONDAY, FRIDAY -> \"busy\";\ndefault -> \"weekday\";"},
			{Use: "case Circle c -> …", Why: "A switch on a sealed type that covers every type needs no default. Java 21+.",
				Like: "Like a sorting tray with one slot for every coin there is: no coin is left over.", Example: "case Circle c -> Math.PI * c.r() * c.r();\ncase Square s -> s.side() * s.side();"},
			{Use: "case Point(int x, var y) ->", Why: "A record pattern takes a record apart into its values. Java 21+. var lets the compiler find each type.",
				Like: "Like opening a lunch box and taking out the sandwich and the apple in one move.", Example: "if (obj instanceof Point(int x, int y)) {\n  return x * x + y * y;\n}"},
			{Use: "case Circle c when c.r() > 10", Keys: []string{"when"}, Why: "A guard: the case matches only when the condition after when is true. Java 21+.",
				Like: "Like a ride at a fair: you need a ticket, and you must also be tall enough.", Example: "case Circle c when c.r() > 10 -> \"large\";\ncase Circle c -> \"small\";"},
			{Use: "case null ->", Why: "Handles null inside the switch. Java 21+. Without it, a switch on null throws NullPointerException.",
				Like: "Like a tray at the post office for letters with no address.", Example: "case null -> \"missing\";\ncase String s -> s.strip();\ndefault -> obj.toString();"},
			{Use: "_", Why: "An unnamed variable for a value you do not use: catch (IOException _), or a lambda _ -> 0. Java 22+.",
				Like: "Like a blank name badge: the seat is taken, but nobody needs to call the person by name.", Example: "map.forEach((key, _) -> System.out.println(key));"},
		}},
		{Title: "Collections, streams, time", Keys: []string{"list", "map", "set", "stream", "for"}, Items: []learnItem{
			{Use: "List.of(a, b) · List.copyOf(xs)", Keys: []string{"list.of", "list.copyof", "copyof", "of"}, Why: "Lists that cannot be changed. List.of is Java 9+, List.copyOf Java 10+. They refuse null items. add or remove throws an exception.",
				Like: "Like a printed menu: you can read it, but you cannot write new dishes on it.", Example: "List<String> roles = List.of(\"admin\", \"user\");\nthis.items = List.copyOf(items);"},
			{Use: "list.getFirst() · getLast()", Keys: []string{"getfirst", "getlast", "reversed", "addfirst", "addlast"}, Why: "The first and last item of a list, deque or LinkedHashSet. reversed() gives a reverse view. Java 21+.",
				Like: "Like the first and last car of a train, named directly.", Example: "var newest = orders.getLast();\nfor (var o : orders.reversed()) System.out.println(o);"},
			{Use: "stream().toList()", Keys: []string{"tolist", "stream", "map", "filter"}, Why: "Collects stream results into a list that cannot be changed. Java 16+.",
				Like: "Like a sealed bag at the end of a sorting belt.", Example: "List<String> names = users.stream()\n  .filter(User::active)\n  .map(User::name).toList();"},
			{Use: "for (var item : items)", Why: "Goes through every item of a list, set or array in order.",
				Like: "Like reading the names on a list from top to bottom.", Example: "for (var item : cart.items()) {\n  total += item.price();\n}"},
			{Use: "LocalDate · Instant · Duration", Keys: []string{"localdate", "localdatetime", "instant", "duration", "zoneddatetime", "period", "java.time"}, Why: "Dates and times from java.time (Java 8+). All its classes are immutable and safe to share between threads.",
				Like: "Like a date printed on a ticket: it never changes, so anyone can read it at any time.", Example: "LocalDate due = LocalDate.now().plusDays(30);\nInstant start = Instant.now();\nDuration took = Duration.between(start, Instant.now());"},
		}},
		{Title: "Resources and threads", Keys: []string{"try", "catch", "throw", "thread", "exception"}, Items: []learnItem{
			{Use: "try (var in = open()) { … }", Keys: []string{"autocloseable", "close"}, Why: "try-with-resources closes each resource at the end, in reverse order, even after an exception. The resource must be AutoCloseable.",
				Like: "Like a door that closes behind you by itself, whatever happens in the room.", Example: "try (var reader = Files.newBufferedReader(path)) {\n  return reader.readLine();\n}"},
			{Use: "opt.orElseThrow()", Keys: []string{"orelsethrow", "orelse", "orelseget", "ifpresent"}, Why: "Gives the value, or throws NoSuchElementException when it is empty. Java 10+. The JDK prefers it to get().",
				Like: "Like a vending machine that gives you the drink, or rings an alarm when the slot is empty.", Example: "User user = repo.findById(id).orElseThrow();"},
			{Use: "newVirtualThreadPerTaskExecutor", Keys: []string{"virtual", "executors"}, Why: "Runs each task on its own virtual thread. Java 21+. Virtual threads are cheap: make one per task, never pool them.",
				Like: "Like paper cups at a water cooler: take a new one each time instead of washing a few.", Example: "try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {\n  urls.forEach(u -> ex.submit(() -> fetch(u)));\n}"},
			{Use: "try (var ex = Executors…)", Keys: []string{"executorservice"}, Why: "An ExecutorService closes itself at the end of try. Java 19+. close() waits until every task has finished.",
				Like: "Like a teacher who waits until every child is back on the bus before it leaves.", Example: "try (var pool = Executors.newFixedThreadPool(4)) {\n  images.forEach(i -> pool.submit(() -> resize(i)));\n}"},
			{Use: "Thread.ofVirtual().start(r)", Keys: []string{"ofvirtual", "startvirtualthread"}, Why: "Starts one virtual thread. Java 21+. Thread.startVirtualThread(r) does the same.",
				Like: "Like calling one helper for one small job.", Example: "Thread t = Thread.ofVirtual().start(() -> send(mail));\nt.join();"},
		}},
		{Title: "Start and tools", Keys: []string{"main", "import"}, Items: []learnItem{
			{Use: "void main() { … }", Why: "A whole program can be one main method, with no class around it. Java 25+.",
				Like: "Like a note on the fridge: no envelope, no stamp, just the message.", Example: "void main() {\n  IO.println(\"Hello, world\");\n}"},
			{Use: "IO.println(x) · IO.readln()", Keys: []string{"io", "println", "readln", "system.out.println"}, Why: "Print a line and read a line. IO is in java.lang, so it needs no import. Java 25+.",
				Like: "Like talking to someone face to face instead of writing a letter.", Example: "String name = IO.readln(\"Name: \");\nIO.println(\"Hi \" + name);"},
			{Use: "import module java.base;", Keys: []string{"module"}, Why: "Imports every public class from every package a module exports. Java 25+. A file with a bare main method gets java.base this way by itself.",
				Like: "Like a library card that opens every room in the building, not one shelf.", Example: "import module java.base;\nimport module java.net.http;"},
			{Use: "java Main.java", Keys: []string{"javac"}, Why: "Runs a source file with no separate compile step. One file: Java 11+. Several files: Java 22+.",
				Like: "Like reading a recipe out loud while you cook, instead of copying it out first.", Example: "java Main.java input.txt"},
			{Use: "jshell", Why: "Type Java one line at a time and see each result at once. Java 9+.",
				Like: "Like a calculator: try one sum, see the answer, try the next.", Example: "jshell\njshell> \"ab\".repeat(3)\n$1 ==> \"ababab\""},
			{Use: "/// Markdown doc comment", Keys: []string{"///", "/**", "javadoc"}, Why: "Documentation comments written in Markdown, each line starting ///. Java 23+.",
				Like: "Like a label on a jar that says what is inside and how to use it.", Example: "/// Returns the total of all lines, in **cents**.\n/// @param items the order lines\nint total(List<Item> items);"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "raw types: List list", Keys: []string{"raw"}, Why: "A generic type with no <…>. The JLS strongly discourages it in new code and may forbid it later. Write List<String>.",
				Like: "Like a box with no label: anything goes in, and you only find out what at the end.", Example: "// instead:\nList<String> names = new ArrayList<>();"},
			{Use: "== on strings", Keys: []string{"=="}, Why: "== checks if two names point to the same String object. Two equal texts can still give false. Use equals.",
				Like: "Like asking 'is this the same copy?' when you meant 'do these say the same?'.", Example: "// instead:\nif (\"yes\".equals(answer)) save();"},
			{Use: "new Integer(5)", Keys: []string{"integer", "new integer", "valueof"}, Why: "The number wrapper constructors are deprecated for removal (Java 16). Use Integer.valueOf(5) or write 5.",
				Like: "Like printing a new coin each time instead of using the coins already in the till.", Example: "// instead:\nInteger n = Integer.valueOf(5);\nint m = 5;"},
			{Use: "finalize()", Keys: []string{"finalize"}, Why: "Finalization is deprecated for removal (Java 18). Use try-with-resources, or a Cleaner for long-lived objects.",
				Like: "Like waiting for the bin lorry to switch off your lights. Switch them off yourself when you leave.", Example: "// instead:\ntry (var in = Files.newInputStream(p)) { load(in); }"},
			{Use: "opt.get()", Keys: []string{"get"}, Why: "Throws on an empty Optional and hides that risk. The JDK prefers orElseThrow().",
				Like: "Like reaching into a box without looking first.", Example: "// instead:\nUser user = findUser(id).orElseThrow();"},
			{Use: "Vector · Date · Calendar", Keys: []string{"vector", "date", "calendar", "hashtable"}, Why: "Old classes. The JDK recommends ArrayList over Vector when you do not need locking. Use java.time for dates.",
				Like: "Like an old plug that no longer fits the wall socket.", Example: "// instead:\nList<String> names = new ArrayList<>();\nLocalDate today = LocalDate.now();"},
			{Use: "pooling virtual threads", Why: "Virtual threads are cheap. The JDK says they should never be pooled. Make a new one per task.",
				Like: "Like keeping used paper cups to wash, when new ones cost almost nothing.", Example: "// instead:\nThread.startVirtualThread(() -> handle(request));"},
		}},
	},
}

var learnKotlin = learnTopic{
	Name:   "Kotlin",
	Match:  []string{"kotlin", ".kt", ".kts"},
	Source: "kotlinlang.org: Basic syntax, Coding conventions, Null safety, Exceptions, Scope functions, Extensions, Data classes, Sealed classes, Object declarations, Inline value classes, Enum classes, Collections overview, Ranges, Java interop, Coroutines basics, Coroutine context and dispatchers, What's new in 1.9 and 2.0 · kotlinx.coroutines API: GlobalScope, Dispatchers.IO · Gradle Kotlin DSL guide",
	Sections: []learnSection{
		{Title: "Values and control flow", Keys: []string{"=", "if", "else"}, Items: []learnItem{
			{Use: "val", Why: "A variable that is set once and cannot be given a new value. The style guide says to use val whenever the value does not change.",
				Like: "Like writing in pen instead of pencil: once it is on the page, it stays.", Example: "val user = repo.find(id)\nval total = items.sumOf { it.price }"},
			{Use: "var", Why: "A variable that can be given a new value later. Use it only when the value really changes.",
				Like: "Like a whiteboard: you can wipe it and write again.", Example: "var count = 0\nfor (line in lines) if (line.isNotBlank()) count++"},
			{Use: "\"Hi $name, ${a + b}\"", Keys: []string{"$", "${"}, Why: "A string template puts values into text. $name for a name, ${…} for any expression. Prefer it to joining strings with +.",
				Like: "Like a form letter with blanks: the values are written into the blanks.", Example: "val msg = \"Hi $name, you have ${cart.size} items\""},
			{Use: "val x = if (a) b else c", Why: "if gives a value, so it can sit on the right of =. Use if for two choices.",
				Like: "Like a fork in the road: either way, you arrive somewhere.", Example: "val label = if (count == 1) \"item\" else \"items\""},
			{Use: "when (x) { … }", Keys: []string{"when", "->"}, Why: "Chooses one branch from many and can give a value. The style guide says to use when for three or more choices.",
				Like: "Like a sorting office: each letter goes to exactly one box.", Example: "200, 201 -> \"OK\"\n404 -> \"Not found\"\nelse -> \"Error $code\""},
			{Use: "if (x is String)", Keys: []string{"is", "!is"}, Why: "Checks the type. After the check, x is treated as a String with no cast (smart cast).",
				Like: "Like opening a door marked 'Kitchen' and already knowing you are in the kitchen.", Example: "if (value is String) println(value.length)"},
			{Use: "val n = try { … } catch …", Keys: []string{"try", "catch"}, Why: "try gives a value: the try result, or the catch result. Kotlin has no checked exceptions.",
				Like: "Like plan A, with plan B ready: either way you get a plan.", Example: "val port = try {\n  env.toInt()\n} catch (e: NumberFormatException) { 8080 }"},
		}},
		{Title: "Null safety", Keys: []string{"null", "?"}, Items: []learnItem{
			{Use: "String?", Why: "A ? after a type means the value may be null. A plain String can never be null; the compiler checks this.",
				Like: "Like a seat marked 'may be empty': you look before you sit.", Example: "var nickname: String? = null\nfun findUser(id: Long): User?"},
			{Use: "a?.b", Keys: []string{"?."}, Why: "The safe call: gives null instead of failing when a is null. Calls can be chained: a?.b?.c.",
				Like: "Like knocking before you enter: if nobody is home, you simply leave.", Example: "val city = user?.address?.city"},
			{Use: "a ?: default", Keys: []string{"?:"}, Why: "The Elvis operator: a if it is not null, otherwise the right side. The right side may be return or throw.",
				Like: "Like 'if no one brought a chair, use the spare one'.", Example: "val name = input ?: \"guest\"\nval user = findUser(id) ?: return null"},
			{Use: "x?.let { … }", Keys: []string{"let", "it"}, Why: "Runs the block only when x is not null. Inside it, it is the value, not null.",
				Like: "Like a parcel that is opened only if it arrives.", Example: "email?.let { sendWelcome(it) }"},
			{Use: "as?", Why: "A safe cast: gives null instead of an exception when the type does not fit.",
				Like: "Like trying a key: if it does not fit, you put it back instead of forcing the lock.", Example: "val user = obj as? User ?: return"},
			{Use: "lateinit var", Keys: []string{"lateinit"}, Why: "A non-null var that is set later, not in the constructor. Reading it before it is set throws an exception.",
				Like: "Like a reserved seat: it is yours, but you must arrive before you can sit.", Example: "private lateinit var binding: ActivityMainBinding"},
		}},
		{Title: "Functions", Keys: []string{"fun", "return"}, Items: []learnItem{
			{Use: "fun double(x: Int) = x * 2", Why: "An expression body: a function of one expression written after =. The style guide prefers it.",
				Like: "Like a one-line answer to a one-line question.", Example: "fun fullName(u: User) = \"${u.first} ${u.last}\""},
			{Use: "fun f(size: Int = 10)", Why: "A default value for a parameter. The style guide prefers it to writing several versions of the function.",
				Like: "Like a coffee order that is 'medium' unless you say otherwise.", Example: "fun greet(name: String = \"guest\") = \"Hi $name\"\ngreet()\ngreet(\"Ana\")"},
			{Use: "fun String.shout() = …", Keys: []string{"extension"}, Why: "An extension function: call it as \"hi\".shout(). It cannot see private members, and it is chosen by the declared type.",
				Like: "Like a clip-on lamp for a desk: it adds light without rebuilding the desk.", Example: "fun String.isEmail() = contains('@')\nif (input.isEmail()) save(input)"},
			{Use: "obj.apply { … }", Keys: []string{"apply"}, Why: "Sets up an object and returns the object. Inside, this is the object.",
				Like: "Like filling in a new form, then handing back the same form.", Example: "val props = Properties().apply {\n  load(file.inputStream())\n}"},
			{Use: "also · run · with", Keys: []string{"also", "run", "with", "takeif"}, Why: "also: a side task such as logging, returns the object. run and with: work on the object, return the result. Do not nest them.",
				Like: "Like tools on a belt: each one has its own job; using two at once gets confusing.", Example: "val saved = repo.save(user).also { log.info(\"saved $it\") }\nval area = with(rect) { width * height }"},
			{Use: "require(x) · check(x)", Keys: []string{"require", "check", "error"}, Why: "require throws IllegalArgumentException for a bad argument. check throws IllegalStateException for a bad state. error(msg) always throws.",
				Like: "Like a door that opens only with a ticket.", Example: "require(age >= 0) { \"age must be >= 0: $age\" }\ncheck(isConnected) { \"not connected\" }"},
		}},
		{Title: "Classes and types", Keys: []string{"class", "object", "interface"}, Items: []learnItem{
			{Use: "data class User(val name: String)", Keys: []string{"data"}, Why: "A class that carries data. Kotlin writes equals, hashCode, toString, copy and component functions. Needs at least one val or var in the constructor.",
				Like: "Like a printed receipt: every line is visible, and two equal receipts compare equal.", Example: "data class User(val name: String, val age: Int)\nval u = User(\"Ana\", 30)\nprintln(u)"},
			{Use: "u.copy(age = 2)", Keys: []string{"copy"}, Why: "A new object with some values changed. The copy is shallow: a list inside is shared, not copied.",
				Like: "Like a photocopy with one line changed by hand. Paper clips on the page are the same clips.", Example: "val older = user.copy(age = user.age + 1)"},
			{Use: "sealed interface Result", Keys: []string{"sealed"}, Why: "All direct subtypes are known when compiling. A when over it needs no else, and a new subtype breaks every when that misses it.",
				Like: "Like a guest list at the door: only the names on it may come in.", Example: "sealed interface Result\ndata class Ok(val data: String) : Result\ndata class Err(val error: Throwable) : Result"},
			{Use: "data object Loading", Why: "A single object whose toString is its name. Kotlin 1.9+. Good for sealed types with no data.",
				Like: "Like a 'Closed' sign: there is only one, and it says what it is.", Example: "sealed interface UiState {\n  data object Loading : UiState\n}"},
			{Use: "@JvmInline value class", Keys: []string{"value", "@jvminline"}, Why: "Wraps one value in its own type, usually with no extra object at run time. UserId and Int cannot be mixed up.",
				Like: "Like a coloured sleeve on a key: same key, but you cannot confuse it with others.", Example: "@JvmInline\nvalue class UserId(val id: Long)"},
			{Use: "companion object", Keys: []string{"companion"}, Why: "Members called on the class name, such as User.create(…). They are members of an object, not Java statics.",
				Like: "Like the front desk of a building: you go there before you have a room.", Example: "class User private constructor(val name: String) {\n  companion object { fun create(n: String) = User(n) }\n}"},
			{Use: "Color.entries", Keys: []string{"entries", "enum"}, Why: "All the values of an enum class as a list. Kotlin 1.9+. Use it instead of values().",
				Like: "Like the list of every colour on a paint chart.", Example: "for (c in Color.entries) println(c.name)"},
		}},
		{Title: "Collections and ranges", Keys: []string{"list", "map", "set", "for", "in"}, Items: []learnItem{
			{Use: "listOf(1, 2)", Keys: []string{"listof", "setof"}, Why: "A read-only List: you can read it, not add or remove. Declare collections with List, Set or Map when you do not change them.",
				Like: "Like a printed menu: you can read it, but you cannot write new dishes on it.", Example: "val roles = listOf(\"admin\", \"user\")"},
			{Use: "mutableListOf()", Keys: []string{"mutablelistof", "mutablemapof", "mutablesetof"}, Why: "A list you can change. A val holding it still allows add and remove; only the variable is fixed.",
				Like: "Like a fixed shelf: the shelf stays, but you can swap the books on it.", Example: "val names = mutableListOf<String>()\nnames.add(\"Ana\")"},
			{Use: "mapOf(\"a\" to 1)", Keys: []string{"mapof", "to"}, Why: "A read-only map. a to b makes a pair of key and value.",
				Like: "Like a coat check: each ticket number leads to one coat.", Example: "val prices = mapOf(\"apple\" to 1.2, \"pear\" to 0.9)\nval p = prices[\"apple\"]"},
			{Use: "xs.filter { … }.map { … }", Keys: []string{"filter", "map", "filternotnull"}, Why: "The style guide prefers these functions to writing loops by hand.",
				Like: "Like a sieve, then a stamp: first keep what you want, then change each piece.", Example: "val emails = users.filter { it.active }.map { it.email }"},
			{Use: "for (i in 0..<n)", Keys: []string{"..<", "..", "until"}, Why: "0..n includes n. 0..<n stops before n. ..< is stable in Kotlin 1.9+.",
				Like: "Like counting stairs: 'up to the top step' or 'up to but not onto it'.", Example: "for (i in 0..<count) println(\"Row $i\")\nif (score in 0..100) save(score)"},
			{Use: "10 downTo 0 step 2", Keys: []string{"downto", "step"}, Why: "downTo counts backwards. step sets the jump between numbers.",
				Like: "Like a countdown that skips every other number.", Example: "for (i in 10 downTo 0 step 2) println(i)"},
		}},
		{Title: "Coroutines", Keys: []string{"coroutine", "scope", "dispatchers"}, Items: []learnItem{
			{Use: "suspend fun load()", Keys: []string{"suspend"}, Why: "A function that can pause without blocking its thread. It can be called only from a coroutine or another suspend function.",
				Like: "Like putting a bookmark in a book: you stop, do something else, then carry on from the same line.", Example: "suspend fun loadUser(id: Long): User =\n  api.getUser(id)"},
			{Use: "coroutineScope { launch { … } }", Keys: []string{"coroutinescope", "launch"}, Why: "launch starts work alongside; coroutineScope waits for all of it. If the parent fails, its children are cancelled.",
				Like: "Like a team leader who does not go home until every helper is done.", Example: "suspend fun refreshAll() = coroutineScope {\n  users.forEach { launch { refresh(it) } }\n}"},
			{Use: "async { … }.await()", Keys: []string{"async", "await", "deferred"}, Why: "async starts work that gives a result. await waits for that result.",
				Like: "Like ordering at a counter and getting a number: you collect the meal when it is called.", Example: "val user = async { api.user(id) }\nval posts = async { api.posts(id) }\nshow(user.await(), posts.await())"},
			{Use: "withContext(Dispatchers.IO)", Keys: []string{"withcontext", "dispatchers.io", "dispatchers.default"}, Why: "Runs a block on another dispatcher, then comes back. IO is for blocking file, network and database calls.",
				Like: "Like sending a heavy parcel by the freight lift, then taking the normal lift back.", Example: "val text = withContext(Dispatchers.IO) {\n  file.readText()\n}"},
			{Use: "flow { emit(x) }", Keys: []string{"flow", "emit", "collect"}, Why: "A stream of values over time. It is cold: the code runs only when someone calls collect, and again for each collect.",
				Like: "Like a tap: water flows only when someone turns it on.", Example: "fun prices(): Flow<Int> = flow {\n  for (p in api.prices()) emit(p)\n}"},
			{Use: "runBlocking { … }", Keys: []string{"runblocking"}, Why: "Blocks the thread until the coroutines finish. Use it only to call suspend code from code that cannot suspend.",
				Like: "Like holding a door open with your body: fine for a moment, not as a habit.", Example: "fun main() = runBlocking {\n  println(loadUser(1))\n}"},
		}},
		{Title: "Naming and tools", Keys: []string{"package", "import", "const"}, Items: []learnItem{
			{Use: "class DeclarationProcessor", Why: "Classes and objects: UpperCamelCase. Functions, properties and locals: lowerCamelCase. Packages: lowercase, no _.",
				Like: "Like a shop sign with capitals, and a to-do list in small letters.", Example: "package com.example.shop\nclass OrderService(private val repo: OrderRepository)"},
			{Use: "const val MAX_COUNT = 8", Why: "Constants are all capitals with _ between words.",
				Like: "Like a road sign in capital letters: fixed, and easy to spot.", Example: "private const val TIMEOUT_MS = 5_000L"},
			{Use: "private val _items", Why: "A backing property starts with _. The public property without _ shows it to others.",
				Like: "Like a shop's stock room behind the counter, and the shelf customers see.", Example: "private val _items = mutableListOf<Item>()\nval items: List<Item> get() = _items"},
			{Use: "4 spaces, trailing comma", Keys: []string{","}, Why: "Indent with four spaces, never tabs. A comma after the last item makes later changes cleaner. No semicolons.",
				Like: "Like leaving a spare hook at the end of a coat rack: adding one more is easy.", Example: "val colors = listOf(\n  \"red\", \"green\", \"blue\",\n)"},
			{Use: "build.gradle.kts", Keys: []string{"gradle", "plugins", "dependencies"}, Why: "A Gradle build written in Kotlin. The .kts ending turns on the Kotlin DSL.",
				Like: "Like a recipe card for building the whole project.", Example: "dependencies {\n  implementation(\"com.squareup.okhttp3:okhttp:4.12.0\")\n}"},
			{Use: "K2 compiler", Keys: []string{"k2"}, Why: "The current Kotlin compiler. Stable and on by default since Kotlin 2.0.",
				Like: "Like a new engine in the same car: you drive it the same way.", Example: "kotlinc Main.kt -include-runtime -d main.jar\njava -jar main.jar"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "x!!", Keys: []string{"!!"}, Why: "Throws NullPointerException when x is null. Use ?., ?: or an if check. Keep !! for the rare case the compiler cannot see.",
				Like: "Like taking off a seat belt because you are sure there will be no crash.", Example: "// instead:\nval len = name?.length ?: 0"},
			{Use: "GlobalScope.launch", Keys: []string{"globalscope"}, Why: "Its coroutines cannot all be cancelled. The coroutines docs call it an antipattern. Use coroutineScope or a scope tied to a lifecycle.",
				Like: "Like letting balloons go: nobody can call them back.", Example: "// instead:\nviewModelScope.launch { loadUser() }"},
			{Use: "values()", Why: "The older way to list enum values. The Kotlin 1.9 notes recommend the entries property instead.",
				Like: "Like reprinting the whole menu each time someone asks what there is.", Example: "// instead:\nfor (c in Color.entries) println(c)"},
			{Use: "var that never changes", Why: "Use val when the value is set once. Readers then know it stays the same.",
				Like: "Like writing a birthday in pencil: it invites changes that should never happen.", Example: "// instead:\nval total = prices.sum()"},
			{Use: "platform type String!", Keys: []string{"string!"}, Why: "A value from Java with unknown nullness. Kotlin does not check it. Give it an explicit type, or add nullability annotations in Java.",
				Like: "Like an unlabelled jar from a neighbour: check it before you cook with it.", Example: "// instead:\nval name: String? = javaUser.name"},
			{Use: "\"a \" + b + \" c\"", Keys: []string{"+"}, Why: "Joining strings with + is harder to read. Use a template: \"a $b c\".",
				Like: "Like gluing words together one by one instead of filling in a form.", Example: "// instead:\nval greeting = \"Hello, $name!\""},
		}},
	},
}
